/**
 * 列表模板的筛选控件。都收 state（ListState<TFilters>）与 name，TFilters 一路保留到这里：
 * name 写错或值类型不对时 tsc 报错。控件只回调，不自己取数。
 * - ListKeywordFilter：关键词，本地镜像加 300ms 防抖再写进 state。
 * - ListStatusFilter：单选。「全部」是 value: null 项（select.md R3），写回 state 时是 undefined。
 */
import { useEffect, useEffectEvent, useState } from "react";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { type ListFilterKey, type ListState, statusFromSelect, statusToSelect } from "./list-model";

export const KEYWORD_DEBOUNCE_MS = 300;

export interface ListKeywordFilterProps<TFilters extends object> {
  state: ListState<TFilters>;
  name: ListFilterKey<TFilters, string>;
  /** 没有可见标签，写进 aria-label，如「搜索用户」。 */
  label: string;
  placeholder?: string;
}

export function ListKeywordFilter<TFilters extends object>({
  state,
  name,
  label,
  placeholder,
}: ListKeywordFilterProps<TFilters>) {
  const value = state.filters[name] as string;
  const [text, setText] = useState(value);
  const [synced, setSynced] = useState(value);
  // state 从外部变了（清除筛选、浏览器后退）：输入框跟着变。
  if (value !== synced) {
    setSynced(value);
    setText(value);
  }
  const commit = useEffectEvent((next: string) => {
    state.setFilters({ [name]: next } as Partial<TFilters>);
  });
  useEffect(() => {
    if (text === synced) return;
    const timer = setTimeout(() => commit(text), KEYWORD_DEBOUNCE_MS);
    return () => clearTimeout(timer);
  }, [text, synced]);
  return (
    <Input
      type="search"
      aria-label={label}
      placeholder={placeholder}
      value={text}
      onChange={(event) => setText(event.target.value)}
      className="w-64"
    />
  );
}

export interface ListStatusOption<TValue> {
  value: TValue;
  label: string;
}

export interface ListStatusFilterProps<
  TFilters extends object,
  TName extends ListFilterKey<TFilters, string | undefined>,
> {
  state: ListState<TFilters>;
  name: TName;
  /** 写进 aria-label，如「状态」。 */
  label: string;
  /** 「全部」项的文案，如「全部状态」。 */
  allLabel: string;
  options: readonly ListStatusOption<NonNullable<TFilters[TName]>>[];
}

export function ListStatusFilter<
  TFilters extends object,
  TName extends ListFilterKey<TFilters, string | undefined>,
>({ state, name, label, allLabel, options }: ListStatusFilterProps<TFilters, TName>) {
  type Value = NonNullable<TFilters[TName]>;
  const items: ListStatusOption<Value | null>[] = [{ value: null, label: allLabel }, ...options];
  const value = statusToSelect(state.filters[name] as Value | undefined);
  return (
    <Select
      items={items}
      value={value}
      onValueChange={(next: Value | null) =>
        state.setFilters({ [name]: statusFromSelect(next) } as Partial<TFilters>)
      }
    >
      <SelectTrigger aria-label={label} className="w-32">
        <SelectValue />
      </SelectTrigger>
      <SelectContent>
        {items.map((item) => (
          <SelectItem key={item.label} value={item.value}>
            {item.label}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}

/**
 * 列表模板的纯逻辑（#21、ADR 0012）：列表状态适配的接口与 URL 语义、页码计算、列声明的类名。
 * 不 import React 运行时，也不 import 任何路由库。测试在 list-model.test.mjs。
 */
import type { ReactNode } from "react";

/**
 * 列表状态适配（ADR 0012）。以 prop 交给 <ListPage state={…}>，不做 Provider。
 * 模板自带两个实现：useLocalListState（本地 state）与 useSearchListState（URL 查询参数）。
 */
export interface ListState<TFilters extends object> {
  filters: TFilters;
  /** 从 1 开始。 */
  page: number;
  /** filters 与缺省值不同。 */
  isFiltered: boolean;
  /** 页码回到 1；URL 后端用 replace。 */
  setFilters: (patch: Partial<TFilters>) => void;
  /** 回到缺省值、页码回到 1；URL 后端用 replace。 */
  clearFilters: () => void;
  /** URL 后端用 push。 */
  setPage: (page: number) => void;
}

/** 列表在 URL 查询参数里的形状：筛选键都可省，page 缺省为 1。 */
export type ListSearch<TFilters extends object> = { [K in keyof TFilters]?: TFilters[K] } & {
  page?: number;
};

/** TFilters 里值类型可以赋给 V 的键。筛选控件用它把 name 限定到合适的键上。 */
export type ListFilterKey<TFilters extends object, V> = {
  [K in keyof TFilters]-?: TFilters[K] extends V ? K : never;
}[keyof TFilters] &
  string;

const FIRST_PAGE = 1;

function valueEqual(a: unknown, b: unknown): boolean {
  if (Array.isArray(a) && Array.isArray(b)) {
    return a.length === b.length && a.every((item, index) => Object.is(item, b[index]));
  }
  return Object.is(a, b);
}

function filterKeys<TFilters extends object>(defaults: TFilters): (keyof TFilters & string)[] {
  return Object.keys(defaults) as (keyof TFilters & string)[];
}

/** 从 search 读出筛选：只读 defaults 里列出的键，search 里没有的取缺省值。 */
export function filtersFromSearch<TFilters extends object>(
  search: object,
  defaults: TFilters,
): TFilters {
  const source = search as Record<string, unknown>;
  const filters = { ...defaults } as Record<string, unknown>;
  for (const key of filterKeys(defaults)) {
    if (source[key] !== undefined) filters[key] = source[key];
  }
  return filters as TFilters;
}

export function isFiltered<TFilters extends object>(
  filters: TFilters,
  defaults: TFilters,
): boolean {
  return filterKeys(defaults).some((key) => !valueEqual(filters[key], defaults[key]));
}

/** 从 search 读页码；缺省或非法时为 1。 */
export function pageFromSearch(search: object): number {
  const raw = (search as { page?: unknown }).page;
  const page = typeof raw === "string" ? Number(raw) : raw;
  return typeof page === "number" && Number.isInteger(page) && page >= FIRST_PAGE
    ? page
    : FIRST_PAGE;
}

function withoutUndefined<T extends object>(search: T): T {
  const entries = Object.entries(search).filter(([, value]) => value !== undefined);
  return Object.fromEntries(entries) as T;
}

/** 改筛选：合并 patch，等于缺省值的键与 page 都从 search 里删掉。其它键保留。 */
export function searchWithFilters<TSearch extends object, TFilters extends object>(
  search: TSearch,
  patch: Partial<TFilters>,
  defaults: TFilters,
): TSearch {
  const next = { ...search, ...patch, page: undefined } as Record<string, unknown>;
  for (const key of filterKeys(defaults)) {
    if (valueEqual(next[key], defaults[key])) next[key] = undefined;
  }
  return withoutUndefined(next) as TSearch;
}

/** 清除筛选：删掉全部筛选键与 page。其它键保留。 */
export function searchWithoutFilters<TSearch extends object, TFilters extends object>(
  search: TSearch,
  defaults: TFilters,
): TSearch {
  const next = { ...search, page: undefined } as Record<string, unknown>;
  for (const key of filterKeys(defaults)) next[key] = undefined;
  return withoutUndefined(next) as TSearch;
}

/** 翻页：第 1 页（含非法页码）从 search 里删掉。 */
export function searchWithPage<TSearch extends object>(search: TSearch, page: number): TSearch {
  const valid = Number.isInteger(page) && page > FIRST_PAGE;
  return withoutUndefined({ ...search, page: valid ? page : undefined });
}

/** 两份 search 是否相同。值为 undefined 的键视为不存在；用来判断「值没变不导航」。 */
export function sameSearch(a: object, b: object): boolean {
  const left = withoutUndefined(a) as Record<string, unknown>;
  const right = withoutUndefined(b) as Record<string, unknown>;
  const keys = Object.keys(left);
  return (
    keys.length === Object.keys(right).length &&
    keys.every((key) => key in right && valueEqual(left[key], right[key]))
  );
}

/** 写查询参数的函数：updater 拿到最新的 search，返回新的 search。 */
export type SetListSearch<TSearch> = (
  updater: (prev: TSearch) => TSearch,
  options: { replace: boolean },
) => void;

/**
 * URL 后端的列表状态适配。useSearchListState 用它；单独导出便于测试。
 * 改筛选与清除筛选用 replace、页码回到 1；翻页用 push；值没变不调用 setSearch。
 */
export function createSearchListState<TFilters extends object, TSearch extends object>(
  search: TSearch,
  setSearch: SetListSearch<TSearch>,
  defaults: TFilters,
): ListState<TFilters> {
  const filters = filtersFromSearch(search, defaults);
  const navigate = (update: (prev: TSearch) => TSearch, replace: boolean) => {
    if (sameSearch(update(search), search)) return;
    setSearch(update, { replace });
  };
  return {
    filters,
    page: pageFromSearch(search),
    isFiltered: isFiltered(filters, defaults),
    setFilters: (patch) => {
      if (sameSearch({ ...filters, ...patch }, filters)) return;
      navigate((prev) => searchWithFilters(prev, patch, defaults), true);
    },
    clearFilters: () => navigate((prev) => searchWithoutFilters(prev, defaults), true),
    setPage: (page) => navigate((prev) => searchWithPage(prev, page), false),
  };
}

/**
 * 本地后端的列表状态适配。useLocalListState 用它；单独导出便于测试。
 * 语义与 URL 后端相同，只是没有 replace／push 之分。
 */
export function createLocalListState<TFilters extends object>(
  current: { filters: TFilters; page: number },
  set: (next: { filters: TFilters; page: number }) => void,
  defaults: TFilters,
): ListState<TFilters> {
  const { filters, page } = current;
  const apply = (next: TFilters) => {
    if (sameSearch(next, filters) && page === FIRST_PAGE) return;
    set({ filters: next, page: FIRST_PAGE });
  };
  return {
    filters,
    page,
    isFiltered: isFiltered(filters, defaults),
    setFilters: (patch) => {
      const next = { ...filters, ...patch };
      if (sameSearch(next, filters)) return;
      apply(next);
    },
    clearFilters: () => apply(defaults),
    setPage: (next) => {
      const target = Number.isInteger(next) && next >= FIRST_PAGE ? next : FIRST_PAGE;
      if (target !== page) set({ filters, page: target });
    },
  };
}

/** 总页数，至少为 1。 */
export function pageCountOf(total: number, pageSize: number): number {
  return Math.max(Math.ceil(total / pageSize), 1);
}

export interface PaginationModel {
  page: number;
  pageCount: number;
  canPrev: boolean;
  canNext: boolean;
  label: string;
}

export function paginationModel(page: number, pageCount: number): PaginationModel {
  return {
    page,
    pageCount,
    canPrev: page > FIRST_PAGE,
    canNext: page < pageCount,
    label: `第 ${page} / ${pageCount} 页`,
  };
}

/** 筛选里「不筛选」是 undefined；Select 的「全部」项是 value: null（select.md R3）。 */
export function statusToSelect<T>(value: T | undefined): T | null {
  return value === undefined ? null : value;
}

export function statusFromSelect<T>(value: T | null): T | undefined {
  return value === null ? undefined : value;
}

// —— 列声明（#21）——

export type ListColumnKind = "text" | "number" | "date" | "actions";

export interface ListColumn<TRow> {
  id: string;
  /** actions 列也写，渲染成 sr-only。 */
  header: string;
  /** number：右对齐、tabular-nums；date：tabular-nums、弱化色；actions：右对齐、表头 sr-only、w-12。 */
  kind?: ListColumnKind;
  /** 宽度类，只加在 TableHead 上；全表恰好一列不写（流动列）。actions 列缺省 w-12。 */
  width?: string;
  cellClassName?: string;
  cell: (row: TRow) => ReactNode;
  /** 骨架条宽度类，缺省 w-2/3。number 与 actions 列的骨架条靠右。 */
  skeleton?: string;
}

export interface ColumnClasses {
  head: string;
  cell: string;
  skeleton: string;
  headerSrOnly: boolean;
}

const KIND_CLASSES: Record<ListColumnKind, { head: string; cell: string; skeleton: string }> = {
  text: { head: "", cell: "", skeleton: "" },
  number: { head: "text-right tabular-nums", cell: "text-right tabular-nums", skeleton: "ml-auto" },
  date: { head: "", cell: "tabular-nums text-muted-foreground", skeleton: "" },
  actions: { head: "text-right", cell: "text-right", skeleton: "ml-auto" },
};

const ACTIONS_WIDTH = "w-12";
const DEFAULT_SKELETON = "w-2/3";

function join(...classes: (string | undefined)[]): string {
  return classes.filter(Boolean).join(" ");
}

function widthOf(column: Pick<ListColumn<unknown>, "kind" | "width">): string | undefined {
  return column.width ?? (column.kind === "actions" ? ACTIONS_WIDTH : undefined);
}

/** 一份列声明推出表头、单元格、骨架三处的类名。 */
export function columnClasses<TRow>(column: ListColumn<TRow>): ColumnClasses {
  const kind = KIND_CLASSES[column.kind ?? "text"];
  return {
    head: join(widthOf(column), kind.head),
    cell: join(kind.cell, column.cellClassName),
    skeleton: join(kind.skeleton, "h-4", column.skeleton ?? DEFAULT_SKELETON),
    headerSrOnly: column.kind === "actions",
  };
}

/** 检查列声明：id 不重复，恰好一列流动列。没有问题时返回 null。 */
export function checkColumns<TRow>(columns: readonly ListColumn<TRow>[]): string | null {
  const ids = columns.map((column) => column.id);
  const duplicated = ids.filter((id, index) => ids.indexOf(id) !== index);
  if (duplicated.length > 0) return `ListColumn 的 id 重复：${duplicated.join("、")}`;
  const fluid = columns.filter((column) => widthOf(column) === undefined).map((c) => c.id);
  if (fluid.length !== 1) {
    return `ListColumn 要恰好一列流动列（不写 width），现在是 ${fluid.length} 列${
      fluid.length > 0 ? `：${fluid.join("、")}` : ""
    }`;
  }
  return null;
}

/**
 * 开发态的列检查，按问题去重：同一条问题只返回一次，`reported` 记下已报过的。没有新问题时返回 null。
 * 消费者每次渲染都传新的列数组时，也不会每次都报。
 */
export function unreportedColumnProblem<TRow>(
  columns: readonly ListColumn<TRow>[],
  reported: Set<string>,
): string | null {
  const problem = checkColumns(columns);
  if (problem === null || reported.has(problem)) return null;
  reported.add(problem);
  return problem;
}

const DEFAULT_SKELETON_ROWS = 5;
const MAX_SKELETON_ROWS = 10;

/** 骨架行数：显式给了就用；否则取页大小，但不超过 10 行；都没有时 5 行。 */
export function skeletonRowCount(rows: number | undefined, pageSize: number | undefined): number {
  if (rows !== undefined) return rows;
  if (pageSize !== undefined) return Math.min(pageSize, MAX_SKELETON_ROWS);
  return DEFAULT_SKELETON_ROWS;
}

/**
 * 列表模板（#21、ADR 0012）。
 * - ListPage：工具条（筛选、计数徽标、主操作）+ 结果区（表格／空态／错误）+ 分页。
 * - ListSection：设置型变体。段头 + 动作行 + 结果区，不带筛选与分页。
 *
 * 契约：
 * - 列只声明一次（ListColumn），同一份声明驱动表头、单元格和骨架。骨架用真 <Table> 与真表头。
 * - state（列表状态适配）与 stale 都是必填 prop。拿到过数据后不再卸载结果区：rows 又变回 undefined 时，
 *   留着上一批数据并按 stale 淡化。stale 时表格与空态淡化，分页条不跟着淡。
 * - ListPage 的根元素是 flex 列，表格、空态、错误三个分支都是它的直接子元素：空态的 flex-1 才能撑满剩余高度。
 *   ListPage 要放在 flex 列里（AppShell 的内容区就是）。不渲染 <main>，<main> 由 AppShell 渲染。
 * 行链接到详情时，在 cell 里用链接适配的 Link，href 是宿主解析好的字符串（ADR 0005）。
 * 选中行、打开详情这类状态不进 ListState，也不触发 stale（#22）。
 */
import { ClipboardListIcon, FilterXIcon, TriangleAlertIcon } from "lucide-react";
import { type ReactNode, useEffect, useId, useState } from "react";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/components/ui/empty";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { formatNumber } from "@/lib/format";
import {
  columnClasses,
  type ListColumn,
  type ListState,
  pageCountOf,
  skeletonRowCount,
  unreportedColumnProblem,
} from "./list-model";
import { ListPagination, type ListPaginationCopy } from "./list-pagination";

/**
 * 判断是否开发态。用字面的 process.env.NODE_ENV，Vite 与 webpack 都会在构建时替换它。
 * 列表模板的注册表条目不依赖应用外壳，所以这里不 import app-shell 的 IS_DEV。
 */
declare const process: { env: { NODE_ENV?: string } };
const IS_DEV = process.env.NODE_ENV !== "production";

/** 已报过的列问题。整个应用共用一份，每条只报一次。 */
const reportedColumnProblems = new Set<string>();

/** stale 淡化（#21）。过渡类常驻，淡入淡出两个方向都有过渡。 */
const FADE = "transition-opacity duration-150 ease-emphasized";
const STALE = "opacity-60";

function fade(stale: boolean): string {
  return stale ? `${FADE} ${STALE}` : FADE;
}

export interface ListEmptyCopy {
  title: string;
  description?: ReactNode;
  icon?: ReactNode;
  /** 空态里的动作，如「新建用户」。筛选后无命中时模板自己放「清除筛选」。 */
  action?: ReactNode;
}

export interface ListPageCopy extends ListPaginationCopy {
  /** 计数徽标，入参是格式化好的数字。 */
  total: (count: string) => string;
  emptyFiltered: ListEmptyCopy;
  clearFilters: string;
  errorTitle: string;
  retry: string;
  selectAll: string;
}

const DEFAULT_COPY: ListPageCopy = {
  label: "分页",
  prev: "上一页",
  next: "下一页",
  total: (count) => `共 ${count} 条`,
  emptyFiltered: { title: "没有符合条件的结果", description: "换个筛选条件，或清除筛选。" },
  clearFilters: "清除筛选",
  errorTitle: "加载失败",
  retry: "重试",
  selectAll: "选择本页全部",
};

/** 多选（可选）。选中状态不进 ListState。 */
export interface ListSelection<TRow> {
  selected: ReadonlySet<string>;
  onSelectedChange: (next: ReadonlySet<string>) => void;
  /** 行复选框的 aria-label，带对象名，如「选择「李雷」」。 */
  rowLabel: (row: TRow) => string;
}

export interface ListPageProps<TRow, TFilters extends object> {
  /** 列表状态适配：useSearchListState 或 useLocalListState 的返回值。 */
  state: ListState<TFilters>;
  columns: readonly ListColumn<TRow>[];
  /** undefined 表示还没拿到过数据，显示骨架。 */
  rows: readonly TRow[] | undefined;
  rowKey: (row: TRow) => string;
  /** 正在换一批数据（TanStack Query 的 isPlaceholderData）。 */
  stale: boolean;
  /** 总条数。显示在计数徽标里，与 pageSize 一起决定分页。还没拿到时传 undefined。 */
  total?: number;
  /** 页大小。不给就不分页。 */
  pageSize?: number;
  /** 工具条左侧的筛选控件。 */
  filters?: ReactNode;
  /** 工具条右侧的主操作，如「新建用户」按钮。 */
  primaryAction?: ReactNode;
  /** 工具条与结果区之间的说明条。 */
  notice?: ReactNode;
  /** 真的没有数据时的空态。 */
  empty: ListEmptyCopy;
  /** 给用户看的错误消息。非空时显示错误分支。 */
  error?: string | null;
  onRetry?: () => void;
  /** 骨架行数。缺省取页大小，不超过 10 行；没有页大小时 5 行。 */
  skeletonRows?: number;
  selection?: ListSelection<TRow>;
  copy?: Partial<ListPageCopy>;
  /** 浮层（对话框、确认框），放在页面最后。 */
  children?: ReactNode;
}

/** 拿到过的值不丢：value 变回 undefined 时返回上一次的值。 */
function useKept<T>(value: T | undefined): T | undefined {
  const [kept, setKept] = useState(value);
  if (value !== undefined && value !== kept) setKept(value);
  return value ?? kept;
}

function useColumnCheck<TRow>(columns: readonly ListColumn<TRow>[]) {
  useEffect(() => {
    if (!IS_DEV) return;
    const problem = unreportedColumnProblem(columns, reportedColumnProblems);
    if (problem !== null) console.error(`[list-page] ${problem}`);
  }, [columns]);
}

export function ListPage<TRow, TFilters extends object>({
  state,
  columns,
  rows,
  rowKey,
  stale,
  total,
  pageSize,
  filters,
  primaryAction,
  notice,
  empty,
  error,
  onRetry,
  skeletonRows,
  selection,
  copy: copyOverrides,
  children,
}: ListPageProps<TRow, TFilters>) {
  const copy = { ...DEFAULT_COPY, ...copyOverrides };
  useColumnCheck(columns);
  const shownRows = useKept(rows);
  const shownTotal = useKept(total);
  const isStale = stale || (rows === undefined && shownRows !== undefined);
  const pageCount =
    shownTotal !== undefined && pageSize !== undefined ? pageCountOf(shownTotal, pageSize) : 1;
  // 分页的列表总显示计数徽标，总数没到时 aria-busy；不分页的列表给了 total 才显示。
  const hasCount = pageSize !== undefined || shownTotal !== undefined;
  const hasToolbar = filters !== undefined || primaryAction !== undefined || hasCount;
  return (
    <div className="flex flex-1 flex-col gap-3 p-4">
      {hasToolbar ? (
        <div className="flex flex-wrap items-center justify-between gap-2">
          <div className="flex flex-wrap items-center gap-2">{filters}</div>
          <div className="flex items-center gap-3">
            {hasCount ? <ListCount total={shownTotal} format={copy.total} /> : null}
            {primaryAction}
          </div>
        </div>
      ) : null}
      {notice}
      {/* 下面三个分支都是根 flex 列的直接子元素，中间不套容器。 */}
      {error ? (
        <ListError message={error} onRetry={onRetry} copy={copy} />
      ) : shownRows === undefined ? (
        <ListTableSkeleton
          columns={columns}
          rows={skeletonRowCount(skeletonRows, pageSize)}
          selection={selection !== undefined}
          copy={copy}
        />
      ) : shownRows.length === 0 ? (
        <ListEmptyState
          stale={isStale}
          {...(state.isFiltered
            ? {
                ...copy.emptyFiltered,
                icon: copy.emptyFiltered.icon ?? <FilterXIcon />,
                action: (
                  <Button variant="outline" size="sm" onClick={state.clearFilters}>
                    {copy.clearFilters}
                  </Button>
                ),
              }
            : { ...empty, icon: empty.icon ?? <ClipboardListIcon /> })}
        />
      ) : (
        <ListTable
          columns={columns}
          rows={shownRows}
          rowKey={rowKey}
          stale={isStale}
          selection={selection}
          copy={copy}
        />
      )}
      {!error && pageSize !== undefined ? (
        <ListPagination
          page={state.page}
          pageCount={pageCount}
          onPageChange={state.setPage}
          copy={copy}
        />
      ) : null}
      {children}
    </div>
  );
}

export interface ListSectionProps<TRow> {
  /** 段标题（h2）。 */
  title: string;
  description?: ReactNode;
  /** 动作行右侧，如「新建密钥」按钮。 */
  action?: ReactNode;
  columns: readonly ListColumn<TRow>[];
  rows: readonly TRow[] | undefined;
  rowKey: (row: TRow) => string;
  empty: ListEmptyCopy;
  error?: string | null;
  onRetry?: () => void;
  /** 骨架行数，缺省 3 行。 */
  skeletonRows?: number;
  copy?: Partial<Pick<ListPageCopy, "errorTitle" | "retry">>;
  /** 浮层，放在段落最后。 */
  children?: ReactNode;
}

const SECTION_SKELETON_ROWS = 3;

/** 设置型变体：段头 + 动作行 + 结果区。没有筛选、分页和 stale。 */
export function ListSection<TRow>({
  title,
  description,
  action,
  columns,
  rows,
  rowKey,
  empty,
  error,
  onRetry,
  skeletonRows = SECTION_SKELETON_ROWS,
  copy: copyOverrides,
  children,
}: ListSectionProps<TRow>) {
  const copy = { ...DEFAULT_COPY, ...copyOverrides };
  const titleId = useId();
  useColumnCheck(columns);
  const shownRows = useKept(rows);
  return (
    <section aria-labelledby={titleId} className="flex flex-col gap-3">
      <div className="flex flex-wrap items-end justify-between gap-2">
        <div className="flex flex-col gap-1">
          <h2 id={titleId} className="text-sm font-medium">
            {title}
          </h2>
          {description ? <p className="text-xs text-muted-foreground">{description}</p> : null}
        </div>
        {action}
      </div>
      {error ? (
        <ListError message={error} onRetry={onRetry} copy={copy} />
      ) : shownRows === undefined ? (
        <ListTableSkeleton columns={columns} rows={skeletonRows} selection={false} copy={copy} />
      ) : shownRows.length === 0 ? (
        <ListEmptyState stale={false} {...empty} icon={empty.icon ?? <ClipboardListIcon />} />
      ) : (
        <ListTable columns={columns} rows={shownRows} rowKey={rowKey} stale={false} copy={copy} />
      )}
      {children}
    </section>
  );
}

/** 计数徽标。还没有总数时 aria-busy，不渲染文案。 */
function ListCount({
  total,
  format,
}: {
  total: number | undefined;
  format: (count: string) => string;
}) {
  return (
    <span role="status" aria-busy={total === undefined} className="text-xs text-muted-foreground">
      {total === undefined ? null : format(formatNumber(total))}
    </span>
  );
}

function ListHeader<TRow>({
  columns,
  selectAll,
}: {
  columns: readonly ListColumn<TRow>[];
  selectAll?: ReactNode;
}) {
  return (
    <TableHeader>
      <TableRow>
        {selectAll !== undefined ? <TableHead className="w-8">{selectAll}</TableHead> : null}
        {columns.map((column) => {
          const classes = columnClasses(column);
          return (
            <TableHead key={column.id} className={classes.head || undefined}>
              {classes.headerSrOnly ? (
                <span className="sr-only">{column.header}</span>
              ) : (
                column.header
              )}
            </TableHead>
          );
        })}
      </TableRow>
    </TableHeader>
  );
}

function ListTable<TRow>({
  columns,
  rows,
  rowKey,
  stale,
  selection,
  copy,
}: {
  columns: readonly ListColumn<TRow>[];
  rows: readonly TRow[];
  rowKey: (row: TRow) => string;
  stale: boolean;
  selection?: ListSelection<TRow>;
  copy: ListPageCopy;
}) {
  const keys = rows.map(rowKey);
  const selectedCount = selection ? keys.filter((key) => selection.selected.has(key)).length : 0;
  const toggle = (key: string, checked: boolean) => {
    if (!selection) return;
    const next = new Set(selection.selected);
    if (checked) next.add(key);
    else next.delete(key);
    selection.onSelectedChange(next);
  };
  const togglePage = (checked: boolean) => {
    if (!selection) return;
    const next = new Set(selection.selected);
    for (const key of keys) {
      if (checked) next.add(key);
      else next.delete(key);
    }
    selection.onSelectedChange(next);
  };
  return (
    <Table aria-busy={stale} className={fade(stale)}>
      <ListHeader
        columns={columns}
        selectAll={
          selection ? (
            <Checkbox
              aria-label={copy.selectAll}
              checked={selectedCount > 0 && selectedCount === keys.length}
              indeterminate={selectedCount > 0 && selectedCount < keys.length}
              onCheckedChange={togglePage}
            />
          ) : undefined
        }
      />
      <TableBody>
        {rows.map((row, index) => {
          const key = keys[index] ?? String(index);
          const selected = selection?.selected.has(key) ?? false;
          return (
            <TableRow key={key} data-state={selected ? "selected" : undefined}>
              {selection ? (
                <TableCell>
                  <Checkbox
                    aria-label={selection.rowLabel(row)}
                    checked={selected}
                    onCheckedChange={(checked) => toggle(key, checked)}
                  />
                </TableCell>
              ) : null}
              {columns.map((column) => (
                <TableCell key={column.id} className={columnClasses(column).cell || undefined}>
                  {column.cell(row)}
                </TableCell>
              ))}
            </TableRow>
          );
        })}
      </TableBody>
    </Table>
  );
}

/** 首次加载的骨架：真 <Table>、真表头，只把单元格换成骨架条。 */
function ListTableSkeleton<TRow>({
  columns,
  rows,
  selection,
  copy,
}: {
  columns: readonly ListColumn<TRow>[];
  rows: number;
  selection: boolean;
  copy: Pick<ListPageCopy, "selectAll">;
}) {
  return (
    <Table aria-busy>
      <ListHeader
        columns={columns}
        selectAll={selection ? <span className="sr-only">{copy.selectAll}</span> : undefined}
      />
      <TableBody>
        {Array.from({ length: rows }, (_, index) => index).map((index) => (
          <TableRow key={index}>
            {selection ? (
              <TableCell>
                <Skeleton className="size-4" />
              </TableCell>
            ) : null}
            {columns.map((column) => (
              <TableCell key={column.id}>
                <Skeleton className={columnClasses(column).skeleton} />
              </TableCell>
            ))}
          </TableRow>
        ))}
      </TableBody>
    </Table>
  );
}

function ListEmptyState({
  stale,
  title,
  description,
  icon,
  action,
}: ListEmptyCopy & { stale: boolean }) {
  return (
    <Empty aria-busy={stale} className={fade(stale)}>
      <EmptyHeader>
        {icon ? <EmptyMedia variant="icon">{icon}</EmptyMedia> : null}
        <EmptyTitle>{title}</EmptyTitle>
        {description ? <EmptyDescription>{description}</EmptyDescription> : null}
      </EmptyHeader>
      {action ? <EmptyContent>{action}</EmptyContent> : null}
    </Empty>
  );
}

function ListError({
  message,
  onRetry,
  copy,
}: {
  message: string;
  onRetry: (() => void) | undefined;
  copy: Pick<ListPageCopy, "errorTitle" | "retry">;
}) {
  return (
    <Empty>
      <EmptyHeader>
        <EmptyMedia variant="icon">
          <TriangleAlertIcon />
        </EmptyMedia>
        <EmptyTitle>{copy.errorTitle}</EmptyTitle>
        <EmptyDescription>{message}</EmptyDescription>
      </EmptyHeader>
      {onRetry ? (
        <EmptyContent>
          <Button variant="outline" size="sm" onClick={onRetry}>
            {copy.retry}
          </Button>
        </EmptyContent>
      ) : null}
    </Empty>
  );
}

/**
 * 列表模板自带的分页（#21）：上一页、下一页，加「第 X / Y 页」。不用原装 pagination。
 * 只有一页时不渲染。按钮不能点时用 disabled + focusableWhenDisabled，焦点不丢。
 */
import { ChevronLeftIcon, ChevronRightIcon } from "lucide-react";
import { Button } from "@/components/ui/button";
import { paginationModel } from "./list-model";

export interface ListPaginationCopy {
  label: string;
  prev: string;
  next: string;
}

const DEFAULT_COPY: ListPaginationCopy = { label: "分页", prev: "上一页", next: "下一页" };

export interface ListPaginationProps {
  /** 从 1 开始。 */
  page: number;
  pageCount: number;
  onPageChange: (page: number) => void;
  copy?: Partial<ListPaginationCopy>;
}

export function ListPagination({
  page,
  pageCount,
  onPageChange,
  copy: copyOverrides,
}: ListPaginationProps) {
  const copy = { ...DEFAULT_COPY, ...copyOverrides };
  const model = paginationModel(page, pageCount);
  if (!model.canPrev && !model.canNext) return null;
  return (
    <nav aria-label={copy.label} className="flex items-center justify-end gap-2">
      <span className="text-xs text-muted-foreground tabular-nums">{model.label}</span>
      <Button
        variant="outline"
        size="sm"
        disabled={!model.canPrev}
        focusableWhenDisabled
        onClick={() => onPageChange(page - 1)}
      >
        <ChevronLeftIcon data-icon="inline-start" />
        {copy.prev}
      </Button>
      <Button
        variant="outline"
        size="sm"
        disabled={!model.canNext}
        focusableWhenDisabled
        onClick={() => onPageChange(page + 1)}
      >
        {copy.next}
        <ChevronRightIcon data-icon="inline-end" />
      </Button>
    </nav>
  );
}

/**
 * 行尾操作菜单（SKILL 第 5 步「表格行操作」）：两个及以上的行操作收进 kebab DropdownMenu。
 * - ListRowMenu：触发器是 ghost icon-xs 按钮加 MoreHorizontalIcon，aria-label 带对象名；菜单与行尾对齐。
 * - ListDisabledMenuItem：暂时不能执行的动作。项仍显示、变灰，右侧写出原因。
 * 不可撤销的动作（删除、吊销）点击只改 use<Feature>Actions 的状态，ConfirmActionDialog 写在菜单外面。
 */
import { MoreHorizontalIcon } from "lucide-react";
import type { ReactNode } from "react";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

export interface ListRowMenuProps {
  /** 触发器的 aria-label，带被操作对象的名字，如「用户「李雷」操作」。 */
  label: string;
  children: ReactNode;
}

export function ListRowMenu({ label, children }: ListRowMenuProps) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger render={<Button variant="ghost" size="icon-xs" aria-label={label} />}>
        <MoreHorizontalIcon />
      </DropdownMenuTrigger>
      {/* 缺省宽度跟触发器走（最小 w-32），带原因的禁用项会折行；改成按内容定宽。 */}
      <DropdownMenuContent align="end" className="w-auto">
        {children}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

export interface ListDisabledMenuItemProps {
  children: ReactNode;
  /** 不能执行的原因，如「不能删除自己」。 */
  reason: string;
}

export function ListDisabledMenuItem({ children, reason }: ListDisabledMenuItemProps) {
  return (
    <DropdownMenuItem disabled>
      {children}
      <span className="ml-auto pl-4 text-xs text-muted-foreground">{reason}</span>
    </DropdownMenuItem>
  );
}

/**
 * 列表状态适配的两个实现（ADR 0012）。都不 import 任何路由库。
 * - useLocalListState(defaults)：本地 state，用于对话框里的选择器这类本地列表。
 * - useSearchListState({ search, setSearch, defaults })：URL 查询参数。
 *   改筛选回第一页且用 replace，翻页用 push，值没变不导航，等于缺省值的键与第 1 页不写进 URL。
 * 语义写在 list-model.ts 的 createLocalListState／createSearchListState 里。
 *
 * defaults 写成模块级常量，列出全部筛选键；「不筛选」的键写 undefined。两个实现都只在首次渲染时读它。
 */
import { useMemo, useState } from "react";
import {
  createLocalListState,
  createSearchListState,
  type ListSearch,
  type ListState,
  type SetListSearch,
} from "./list-model";

export function useLocalListState<TFilters extends object>(
  defaults: TFilters,
): ListState<TFilters> {
  const [initial] = useState(defaults);
  const [current, setCurrent] = useState({ filters: initial, page: 1 });
  return useMemo(() => createLocalListState(current, setCurrent, initial), [current, initial]);
}

export interface SearchListStateOptions<TFilters extends object, TSearch extends object> {
  /** 路由库读出的查询参数（TanStack：Route.useSearch()）。可以带列表之外的键，模板原样保留。 */
  search: TSearch;
  /** 写查询参数。TanStack：(updater, { replace }) => navigate({ search: updater, replace })。 */
  setSearch: SetListSearch<TSearch>;
  defaults: TFilters;
}

export function useSearchListState<
  TFilters extends object,
  TSearch extends ListSearch<TFilters> = ListSearch<TFilters>,
>({ search, setSearch, defaults }: SearchListStateOptions<TFilters, TSearch>): ListState<TFilters> {
  const [initial] = useState(defaults);
  return useMemo(
    () => createSearchListState(search, setSearch, initial),
    [search, setSearch, initial],
  );
}
